Given an array of integers, the task is to insert an element at the beginning of the array. Examples:Input: arr[] = [10, 20, 30, 40], ele = 50Output: [50, 10, 20, 30, 40]Input: arr[] = [], ele = 20Output: [20]Table of Content[Approach 1] Using Built-In Methods[Approach 2] Using Custom Method[Approach 1] Using Built-In MethodsWe will use library methods like insert() in C++, Python and C#, add() in Java and unshift() in JavaScript.
            C++

    // C++ program to insert given element at the beginning 
// of an array

#include <iostream>
#include <vector>
using namespace std;

int main() {  
    vector<int> arr = {10, 20, 30, 40};
  	int element = 50;
    cout << "Array before insertion\n";
    for (int i = 0; i < arr.size(); i++)
        cout << arr[i] << " ";

  	// Insert element at the beginning
    arr.insert(arr.begin(), element);

    cout << "\nArray after insertion\n";
    for (int i = 0; i < arr.size(); i++)
        cout << arr[i] << " ";

    return 0;
}


